/* 砚台 · 角色书架 V1.4.1 · 酒馆助手版
 * 创意与测试：阿砚 · 代码：Codex
 * 导入全局脚本。与独立扩展版二选一，共用书架设置。
 * All startup code and CSS are included. Remote releases are fetched only on explicit update actions.
 */
(() => {
    const scriptWindow = globalThis;
    const host = scriptWindow.parent;
    const key = Symbol.for("jingdu.bookshelf.helper.runtime");
    if (host === scriptWindow || !host.SillyTavern?.getContext) {
        scriptWindow.toastr?.error('请导入酒馆助手的全局脚本库。', '砚台 · 角色书架');
        return;
    }
    const existing = host[key];
    if (existing && !existing.disposed) {
        if (existing.frame?.isConnected) {
            host.toastr?.info('书架脚本已有一份正在运行，请只启用一份。', '砚台 · 角色书架');
            return;
        }
        existing.dispose();
    }
    const runtime = {
        // An instance marker, not a secret. Works on ordinary HTTP/LAN addresses too.
        token: Date.now().toString(36) + '-' + Math.random().toString(36).slice(2), frame: scriptWindow.frameElement,
        scriptId: typeof scriptWindow.getScriptId === 'function' ? scriptWindow.getScriptId() : 'dfe86938-8c9f-461a-b382-75b047b26ff2',
        state: 'starting', disposed: false, script: null, style: null, stop: null,
        dispose() {
            if (runtime.disposed) return;
            runtime.disposed = true;
            scriptWindow.removeEventListener('pagehide', runtime.dispose);
            try { runtime.stop?.(); }
            finally {
                runtime.style?.remove();
                runtime.script?.remove();
                if (host[key] === runtime) delete host[key];
            }
        },
    };
    host[key] = runtime;
    scriptWindow.addEventListener('pagehide', runtime.dispose, { once: true });
    const module = host.document.createElement('script');
    module.type = 'module';
    module.id = 'jd-bookshelf-helper-module';
    runtime.script = module;
    // Execute native imports in the parent realm, never a second ST instance in an iframe.
    module.textContent = '(async () => { const runtime = globalThis[Symbol.for("jingdu.bookshelf.helper.runtime")];'
        + 'if (!runtime || runtime.disposed || runtime.token !== ' + JSON.stringify(runtime.token) + ') return;\n'
        + "\ntry {\n    if (runtime.disposed) return;\n    if (!globalThis.SillyTavern?.getContext) throw new Error('请在 SillyTavern 的酒馆助手全局脚本中启用。');\n    if (document.getElementById('jd-bookshelf-settings') || document.getElementById('jd-bookshelf-open')) {\n        globalThis.toastr?.info('独立扩展版书架已经运行。请停用独立版并刷新，再启用本脚本。', '砚台 · 角色书架');\n        runtime.dispose();\n        return;\n    }\n    const style = document.createElement('style');\n    style.id = 'jd-bookshelf-helper-style';\n    style.textContent = \"/* Static, scoped UI. Uses the active theme's colors and font.\\n   Underline/accent colors are decorative; readable controls use body ink. */\\n.jd-bookshelf,.jd-shelf-dialog{\\n  --shelf-ink:var(--SmartThemeBodyColor,#ece8df);\\n  --shelf-accent:var(--SmartThemeUnderlineColor,#c6b590);\\n  --shelf-muted:var(--SmartThemeEmColor,#aeb8ac);\\n  --shelf-line:var(--SmartThemeBorderColor,#45564a);\\n  --shelf-panel:var(--SmartThemeBlurTintColor,#14201b);\\n  --shelf-inset:var(--SmartThemeUserMesBlurTintColor,#1b2a21);\\n  --shelf-font:var(--jd-font,var(--mainFontFamily,serif));\\n  box-sizing:border-box;color:var(--shelf-ink);font-family:var(--shelf-font);\\n  line-height:1.65;text-align:left;text-indent:0;text-shadow:none;\\n}\\n@supports(color:color-mix(in srgb,#000 50%,#fff)){\\n  .jd-bookshelf,.jd-shelf-dialog{\\n    --shelf-muted:color-mix(in srgb,var(--shelf-ink) 60%,var(--shelf-panel));\\n    --shelf-soft-line:color-mix(in srgb,var(--shelf-line) 70%,var(--shelf-panel));\\n  }\\n}\\n.jd-bookshelf *,.jd-shelf-dialog *{box-sizing:border-box;text-indent:0!important;text-shadow:none!important;}\\n.jd-bookshelf button,.jd-shelf-dialog button{\\n  font-family:inherit;cursor:pointer;appearance:none;color:inherit;letter-spacing:inherit;\\n  text-transform:none;text-shadow:none;box-shadow:none;filter:none;transition:none;\\n}\\n.jd-bookshelf button:disabled,.jd-shelf-dialog button:disabled{cursor:wait;opacity:.58;}\\n.jd-bookshelf :is(button,input):focus-visible,.jd-shelf-dialog :is(button,input):focus-visible{outline:2px solid var(--shelf-ink);outline-offset:3px;}\\n.jd-bookshelf{width:100%;min-width:0;max-width:1420px;margin:0 auto;padding:16px 20px 28px;container-type:inline-size;}\\n#chat.jd-bookshelf-home{padding:0!important;overflow-y:auto;}\\n#chat.jd-bookshelf-home>.jd-bookshelf{flex:0 0 auto;}\\n/* Replace only native welcome content, not arbitrary children / popup hosts.\\n   Keep the native composer and extension entry points available. */\\nbody.jd-bookshelf-home-active #chat.jd-bookshelf-home>.welcomePanel,\\nbody.jd-bookshelf-home-active #chat.jd-bookshelf-home>.mes:is([type=\\\"welcome\\\"],[type=\\\"welcome_prompt\\\"],[type=\\\"assistant_message\\\"],[type=\\\"assistant_note\\\"]){display:none!important;}\\n#jd-bookshelf-return{flex:0 0 auto;width:auto;white-space:nowrap;text-indent:0;text-shadow:none;}\\n#jd-bookshelf-return:focus-visible{outline:2px solid currentColor;outline-offset:2px;}\\n.jd-bookshelf .jd-text-button,.jd-shelf-dialog .jd-text-button{padding:5px 0;min-height:30px;border:0;background:none;font-size:12px;line-height:1.5;color:var(--shelf-muted);}\\n.jd-bookshelf .jd-text-button:hover,.jd-shelf-dialog .jd-text-button:hover{color:var(--shelf-ink);}\\n.jd-shelf-toolbar{position:relative;z-index:3;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px 12px;margin:0;}\\n.jd-shelf-navigation{display:flex;align-items:center;gap:2px;min-width:0;}\\n.jd-tabs{display:flex;align-items:center;gap:2px;flex:0 0 auto;}\\n.jd-bookshelf .jd-tab{background:none;border:1px solid transparent;border-radius:3px;padding:5px 10px;min-height:40px;font-size:14px;color:var(--shelf-muted);}\\n.jd-bookshelf .jd-tab[aria-pressed=true]{color:var(--shelf-ink);font-weight:600;border-color:var(--shelf-line);border-bottom-color:currentColor;background:var(--shelf-panel);}\\n.jd-bookshelf .jd-native-home{justify-self:end;margin:0;white-space:nowrap;}\\n.jd-bookshelf .jd-input,.jd-shelf-dialog .jd-input{display:block;width:100%;min-width:0;padding:10px 12px;border:1px solid var(--shelf-line);border-radius:3px;background:var(--shelf-panel);color:var(--shelf-ink);font:14px/1.5 var(--shelf-font);box-shadow:none;}\\n.jd-bookshelf .jd-search{grid-column:1/-1;max-width:none;margin:0;padding:9px 12px;}\\n.jd-sort-control{position:relative;flex:0 0 auto;}\\n.jd-bookshelf .jd-sort-toggle[aria-expanded=true]{border-color:var(--shelf-line);}\\n.jd-sort-menu{position:absolute;inset:calc(100% + 5px) auto auto 0;z-index:5;width:164px;max-width:calc(100vw - 32px);max-height:min(260px,calc(100dvh - 140px));overflow:auto;padding:5px;border:1px solid var(--shelf-line);border-radius:5px;background:var(--shelf-panel);box-shadow:0 6px 22px rgba(0,0,0,.16);}\\n.jd-sort-menu[hidden]{display:none!important;}\\n@supports(color:rgb(from red r g b)){\\n  .jd-sort-menu{background:rgb(from var(--shelf-panel) r g b / .96);}\\n}\\n.jd-bookshelf .jd-sort-option{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:40px;margin:0;padding:8px 10px;border:0;border-radius:3px;background:none;text-align:left;color:var(--shelf-muted);font:13px/1.5 var(--shelf-font);white-space:nowrap;}\\n.jd-bookshelf .jd-sort-option:hover,.jd-bookshelf .jd-sort-option:focus-visible{background:var(--shelf-inset);outline-offset:-2px;}\\n.jd-sort-mark{visibility:hidden;}\\n.jd-sort-option[aria-checked=true] .jd-sort-mark{visibility:visible;}\\n.jd-input::placeholder{color:var(--shelf-muted);opacity:1;}\\n.jd-shelf-info{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px 12px;margin:4px 0 10px;color:var(--shelf-muted);font-size:12px;}\\n.jd-shelf-info>.jd-text-button{margin-left:auto;}\\n.jd-card-tally{padding-inline-start:.35em;}\\n.jd-sort-status{font-size:11px;}\\n.jd-shelf-notice{margin:0;color:var(--shelf-ink);font-size:13px;line-height:1.7;}\\n.jd-shelf-notice:not(:empty){margin:12px 0;}\\n.jd-story-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px 17px;align-items:start;}\\n.jd-story-card{position:relative;min-width:0;border:1px solid var(--shelf-soft-line,var(--shelf-line));border-radius:5px;background:var(--shelf-panel);overflow:hidden;box-shadow:none!important;backdrop-filter:none!important;}\\n.jd-story-card:focus-within,.jd-story-card:hover{border-color:var(--shelf-accent);}\\n.jd-bookshelf .jd-open-card{display:block;width:100%;margin:0;padding:0;border:0;background:none;text-align:left;overflow:hidden;}\\n.jd-cover{position:relative;display:block;width:100%;aspect-ratio:3/4;overflow:hidden;background:var(--shelf-inset);border-bottom:1px solid var(--shelf-soft-line,var(--shelf-line));}\\n.jd-cover img{position:absolute;inset:0;display:block;width:100%;height:100%;max-width:none;max-height:none;object-fit:cover;object-position:50% 25%;border-radius:0;box-shadow:none;filter:none;}\\n.jd-cover-letter{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:50px;font-weight:400;letter-spacing:.1em;color:var(--shelf-ink);}\\n.jd-cover-letter::before,.jd-cover-letter::after{content:\\\"\\\";position:absolute;width:52%;height:55%;border:1px solid var(--shelf-line);}\\n.jd-cover-letter::after{width:45%;height:64%;}\\n.jd-save-count{position:absolute;left:10px;bottom:10px;padding:3px 8px;border:1px solid var(--shelf-line);border-radius:3px;background:var(--shelf-panel);color:var(--shelf-ink);font-size:11px;line-height:1.6;z-index:1;}\\n.jd-card-tools{position:absolute;top:8px;right:8px;display:flex;gap:5px;z-index:2;}\\n.jd-bookshelf .jd-icon-button,.jd-shelf-dialog .jd-icon-button{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;min-width:32px;min-height:32px;margin:0;padding:0 6px;border:1px solid var(--shelf-line);border-radius:3px;background:var(--shelf-panel);font:19px/1.3 system-ui,sans-serif;color:var(--shelf-muted);}\\n.jd-bookshelf .jd-favorite[aria-pressed=true],.jd-bookshelf .jd-icon-button:hover,.jd-shelf-dialog .jd-icon-button:hover{color:var(--shelf-ink);border-color:currentColor;}\\n.jd-bookshelf .jd-pin[aria-pressed=true]{color:var(--shelf-ink);border-color:currentColor;}\\n.jd-pin[aria-pressed=true] svg path{fill:currentColor;fill-opacity:.22;}\\n.jd-card-body{padding:14px 14px 12px;}\\n.jd-card-body h3{margin:0 0 5px!important;font:400 22px/1.5 var(--shelf-font)!important;letter-spacing:.04em;color:var(--shelf-ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\\n.jd-card-tags{margin:0 0 13px!important;font-size:12px!important;line-height:1.6!important;min-height:1.6em;color:var(--shelf-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\\n.jd-card-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px;padding-top:9px;border-top:1px solid var(--shelf-soft-line,var(--shelf-line));}\\n.jd-last-played{font-size:11px;line-height:1.5;color:var(--shelf-muted);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\\n.jd-card-action{flex-shrink:0;font-size:11px;line-height:1.5;color:var(--shelf-muted);}\\n.jd-empty{grid-column:1/-1;padding:45px 10px;color:var(--shelf-muted);text-align:center;font-size:14px;}\\n.jd-shelf-dialog{width:min(620px,calc(100vw - 24px));max-width:calc(100vw - 24px);max-height:calc(100dvh - 32px);padding:0;margin:auto;border:1px solid var(--shelf-line);border-top:2px solid var(--shelf-accent);border-radius:5px;background:var(--shelf-panel);box-shadow:none!important;backdrop-filter:none!important;overflow:auto;scrollbar-width:thin;}\\n.jd-shelf-dialog::backdrop{background:rgba(0,0,0,.65);backdrop-filter:none!important;}\\n.jd-shelf-dialog.jd-shelf-wide{width:min(1180px,calc(100vw - 24px));}\\n.jd-dialog-head{position:sticky;top:0;z-index:3;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 20px;background:var(--shelf-panel);border-bottom:1px solid var(--shelf-line);}\\n.jd-dialog-head h2{margin:0!important;font:400 22px/1.4 var(--shelf-font)!important;color:var(--shelf-ink);}\\n.jd-dialog-body{padding:18px 20px 22px;}\\n.jd-shelf-dialog>.jd-shelf-notice:not(:empty){padding:0 20px 14px;margin:0;}\\n.jd-shelf-wide>.jd-dialog-body{padding:0;}\\n.jd-dialog-intro{margin:0 0 17px;font-size:13px;color:var(--shelf-muted);line-height:1.7;}\\n.jd-save-list{display:flex;flex-direction:column;gap:9px;}\\n.jd-shelf-dialog.jd-archives-dialog{width:min(760px,calc(100vw - 24px));}\\n.jd-save-row{display:flex;align-items:center;gap:12px;padding:11px 12px;border:1px solid var(--shelf-line);border-radius:3px;background:var(--shelf-inset);}\\n.jd-shelf-dialog .jd-open-chat{flex:1;display:block;min-width:0;padding:0;border:0;background:none;text-align:left;}\\n.jd-open-chat strong{display:block;margin-bottom:5px;font-size:17px;font-weight:400;line-height:1.5;overflow-wrap:anywhere;color:var(--shelf-ink);}\\n.jd-open-chat small{display:block;font-size:11px;line-height:1.7;color:var(--shelf-muted);font-variant-numeric:tabular-nums;}\\n.jd-save-preview{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;line-clamp:3;overflow:hidden;max-height:5.1em;margin-top:9px;font-size:14px;line-height:1.7;color:var(--shelf-ink);font-weight:400;white-space:normal;overflow-wrap:anywhere;}\\n.jd-save-preview.jd-preview-empty{font-size:12px;color:var(--shelf-muted);}\\n.jd-archives-dialog .jd-save-row{position:relative;align-items:flex-start;padding:14px;}\\n.jd-archives-dialog .jd-open-chat>strong,.jd-archives-dialog .jd-open-chat>small{padding-right:78px;}\\n.jd-archives-dialog .jd-save-tools{position:absolute;top:14px;right:14px;display:flex;gap:5px;}\\n.jd-shelf-dialog .jd-delete-chat{font-size:13px;}\\n.jd-save-row:hover{border-color:var(--shelf-accent);}\\n.jd-dialog-footer{display:flex;justify-content:flex-end;margin-top:20px;}\\n.jd-shelf-dialog .jd-primary-button{display:block;margin:18px 0 0 auto;padding:9px 15px;border:1px solid var(--shelf-line);border-radius:3px;background:var(--shelf-inset);color:var(--shelf-ink);font-size:14px;line-height:1.5;}\\n.jd-delete-name{display:block;margin:0 0 8px;font-size:18px;overflow-wrap:anywhere;}\\n.jd-delete-file{margin:0 0 16px;font-size:12px;color:var(--shelf-muted);overflow-wrap:anywhere;}\\n.jd-delete-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px;}\\n.jd-shelf-dialog .jd-delete-actions button{margin:0;padding:9px 15px;min-height:42px;border:1px solid var(--shelf-line);border-radius:3px;font-size:14px;line-height:1.5;}\\n.jd-shelf-dialog .jd-secondary-button{background:none;color:var(--shelf-muted);}\\n.jd-shelf-dialog .jd-delete-confirm{color:var(--shelf-ink);border-color:currentColor;}\\n.jd-crop-preview{width:min(100%,320px,34dvh);margin:0 auto 18px;border:1px solid var(--shelf-line);border-radius:3px;}\\n.jd-crop-label{display:grid;grid-template-columns:5em minmax(0,1fr);align-items:center;gap:14px;margin:14px 0;font-size:13px;}\\n.jd-crop-label input{width:100%;accent-color:var(--shelf-ink);}\\n#jd-bookshelf-open[aria-disabled=\\\"true\\\"]{opacity:.55;cursor:wait;}\\n#jd-bookshelf-settings-content>small{display:block;margin:8px 0;}\\n#jd-bookshelf-settings-content>.jd-install-status{color:var(--SmartThemeEmColor);}\\n#jd-bookshelf-settings .menu_button{width:auto;}\\n@container(min-width:1050px){.jd-story-grid{grid-template-columns:repeat(4,minmax(0,1fr));}}\\n@container(max-width:650px){\\n  .jd-story-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px 12px;}\\n  .jd-shelf-toolbar{gap:9px 8px;}\\n  .jd-bookshelf .jd-tab{padding:5px 8px;font-size:13px;}\\n  .jd-bookshelf .jd-search{font-size:16px;}\\n  .jd-card-body{padding:11px 10px 10px;}\\n  .jd-card-body h3{font-size:19px!important;}\\n  .jd-card-tags{font-size:11px!important;margin-bottom:10px!important;}\\n  .jd-card-bottom{flex-wrap:wrap;gap:3px 8px;}\\n  .jd-card-action{margin-left:auto;}\\n}\\n@media(max-width:650px){\\n  .jd-card-tools{top:6px;right:6px;gap:4px;}\\n  .jd-bookshelf .jd-card-tools .jd-icon-button{position:relative;width:26px;height:26px;min-width:26px;min-height:26px;padding:0;border-radius:3px;font-size:16px;}\\n  .jd-card-tools .jd-icon-button svg{width:15px;height:15px;}\\n  .jd-card-tools .jd-icon-button::after{content:\\\"\\\";position:absolute;inset:-2px;}\\n  .jd-save-preview{-webkit-line-clamp:4;line-clamp:4;max-height:6.8em;}\\n  .jd-bookshelf{padding:12px 12px 24px;}\\n  .jd-story-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px 12px;}\\n  .jd-dialog-head{padding:13px 15px;}\\n  .jd-dialog-body{padding:16px 14px 20px;}\\n  .jd-shelf-dialog .jd-input{font-size:16px;}\\n  .jd-shelf-wide .jd-bookshelf{padding:12px 12px 24px;}\\n  .jd-shelf-dialog{max-height:calc(100dvh - 24px);}\\n  .jd-cover img{content-visibility:auto;}\\n}\\n@media(prefers-reduced-motion:reduce){.jd-bookshelf *,.jd-shelf-dialog *{scroll-behavior:auto!important;}}\\n\\n/* Archive-only new-chat entry. */\\n.jd-archive-toolbar{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px 14px;margin-bottom:16px;}\\n.jd-archive-toolbar>.jd-dialog-intro{margin:0;}\\n.jd-shelf-dialog .jd-archive-toolbar>.jd-new-chat{min-height:40px;flex-shrink:0;color:var(--shelf-ink);font-size:14px;}\\n.jd-loading{margin:10px 0 24px;font-size:14px;color:var(--shelf-muted);}\\n.jd-dialog-footer{justify-content:space-between;flex-wrap:wrap;gap:8px 20px;}\\n\\n/* Folders stay behind one menu; bulk controls exist only while organizing. */\\n.jd-bookshelf [hidden]{display:none!important;}\\n.jd-folder-control{position:relative;min-width:0;}\\n.jd-bookshelf .jd-folder-toggle{max-width:clamp(80px,22vw,180px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:middle;}\\n.jd-folder-menu{position:absolute;inset:calc(100% + 5px) auto auto 0;z-index:6;width:228px;max-width:calc(100vw - 52px);max-height:min(340px,60dvh);overflow:auto;padding:5px;border:1px solid var(--shelf-line);border-radius:5px;background:var(--shelf-panel);box-shadow:0 6px 22px rgba(0,0,0,.16);}\\n@supports(color:rgb(from red r g b)){.jd-folder-menu{background:rgb(from var(--shelf-panel) r g b / .98);}}\\n.jd-bookshelf .jd-folder-option,.jd-shelf-dialog .jd-folder-option{display:block;width:100%;min-height:42px;margin:0;padding:9px 10px;border:0;border-radius:3px;background:none;color:var(--shelf-ink);font:14px/1.5 var(--shelf-font);text-align:left;overflow-wrap:anywhere;}\\n.jd-folder-option[aria-pressed=true],.jd-folder-option:hover,.jd-folder-option:focus-visible,.jd-folder-option.jd-drop-target{background:var(--shelf-inset);outline-offset:-2px;}\\n.jd-folder-option[aria-pressed=true]{font-weight:600;}\\n.jd-folder-option.jd-drop-target{outline:2px solid var(--shelf-ink);outline-offset:-2px;}\\n.jd-folder-actions{border-top:1px solid var(--shelf-line);margin-top:4px;padding-top:4px;}\\n.jd-shelf-info>.jd-organize{margin-left:auto;}\\n.jd-shelf-info>.jd-organize~.jd-text-button{margin-left:0;}\\n.jd-organizer-bar{display:flex;align-items:center;flex-wrap:wrap;gap:4px 18px;padding:7px 10px;margin:0 0 12px;border:1px solid var(--shelf-line);border-radius:3px;background:var(--shelf-panel);font-size:12px;}\\n.jd-organizer-bar>.jd-text-button:last-child{margin-left:auto;}\\n.jd-bookshelf .jd-organizer-bar>.jd-text-button{min-height:36px;}\\n.jd-selected-count{font-variant-numeric:tabular-nums;}\\n.jd-select-card{display:none!important;}\\n.jd-organizing .jd-card-tools{display:none;}\\n.jd-organizing .jd-select-card{position:absolute;top:9px;left:9px;display:flex!important;align-items:center;justify-content:center;width:30px;height:30px;margin:0;padding:0;border:1px solid var(--shelf-ink);border-radius:3px;background:var(--shelf-panel);color:var(--shelf-ink);font:18px/1 system-ui;z-index:2;}\\n.jd-organizing .jd-selected{outline:2px solid var(--shelf-ink);outline-offset:-2px;}\\n.jd-organizing .jd-assistant-card{opacity:.55;pointer-events:none;}\\n.jd-dragging{opacity:.6;}\\n.jd-open-card{-webkit-touch-callout:none;user-select:none;touch-action:pan-y;}\\n.jd-pager{display: